import pytest

from bedrock_protocol import v2168, v2193

versions = [v2168, v2193]

# generated by gophertunnel 218ac3f:
# packet.CameraPresets{Presets: []protocol.CameraPreset{{Name: "bare", Parent: ""},
# {Name: "loaded", Parent: "minecraft:free", PosX: Option(1), PosY: Option(2),
# PosZ: Option(3), RotX: Option(0.5), RotY: Option(0.25), RotationSpeed: Option(4),
# SnapToTarget: Option(true), HorizontalRotationLimit: Option(Vec2{1,2}),
# VerticalRotationLimit: Option(Vec2{3,4}), ContinueTargeting: Option(false),
# TrackingRadius: Option(8), ViewOffset: Option(Vec2{5,6}),
# EntityOffset: Option(Vec3{7,8,9}), Radius: Option(16), MinYawLimit: Option(-90),
# MaxYawLimit: Option(90), AudioListener: Option(1), PlayerEffects: Option(true),
# ControlScheme: Option(2)}}}
TWO_PRESETS = bytes.fromhex(
    ""
)

TWO_PRESETS_PACKETS = {
    version: version.CameraPresetsPacket(
        camera_presets=version.CameraPresets(
            presets=[
                version.CameraPreset(name="bare"),
                version.CameraPreset(
                    name="loaded",
                    inherit_from="minecraft:free",
                    pos_x=1.0,
                    pos_y=2.0,
                    pos_z=3.0,
                    rot_x=0.5,
                    rot_y=0.25,
                    camera_rotation_speed=4.0,
                    snap_to_target=True,
                    horizontal_rotation_limit=version.Vec2(x=1.0, y=2.0),
                    vertical_rotation_limit=version.Vec2(x=3.0, y=4.0),
                    continue_targeting=False,
                    tracking_radius=8.0,
                    view_offset=version.Vec2(x=5.0, y=6.0),
                    entity_offset=version.Vec3(x=7.0, y=8.0, z=9.0),
                    radius=16.0,
                    yaw_limit_min=-90.0,
                    yaw_limit_max=90.0,
                    listener=version.CameraPreset.AudioListener.PLAYER,
                    player_effects=True,
                    control_scheme=version.Scheme.CAMERA_RELATIVE_STRAFE,
                ),
            ]
        )
    )
    for version in versions
}


def test_camera_presets_2168_encodes_to_its_golden():
    assert bytes(TWO_PRESETS_PACKETS[v2168]) == TWO_PRESETS


def test_camera_presets_2168_decodes_from_its_golden():
    assert v2168.CameraPresetsPacket.from_bytes(TWO_PRESETS) == TWO_PRESETS_PACKETS[v2168]


def test_camera_presets_2193_grows_each_preset_by_the_starting_rotation_bytes():
    assert len(bytes(TWO_PRESETS_PACKETS[v2193])) == len(TWO_PRESETS) + 4


def test_camera_presets_2193_rejects_a_2168_body():
    with pytest.raises(ValueError, match="at byte"):
        v2193.CameraPresetsPacket.from_bytes(TWO_PRESETS)


def test_camera_presets_2193_round_trips_without_a_starting_rotation():
    packet = TWO_PRESETS_PACKETS[v2193]
    assert v2193.CameraPresetsPacket.from_bytes(bytes(packet)) == packet


def test_camera_presets_2193_round_trips_a_starting_rotation():
    packet = v2193.CameraPresetsPacket(
        camera_presets=v2193.CameraPresets(
            presets=[
                v2193.CameraPreset(
                    name="bare",
                    apply_inherited_starting_rotation=True,
                    starting_rot=v2193.Vec2(x=10.0, y=20.0),
                )
            ]
        )
    )
    assert v2193.CameraPresetsPacket.from_bytes(bytes(packet)) == packet
